// Builds one email from all CRM rows: new leads in the last 24 hours,
// the HOT ones among them, and follow-ups that are due today or overdue.
const rows = $input.all().map((i) => i.json).filter((r) => r.lead_id);
const now = new Date();
const dayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
const today = now.toISOString().slice(0, 10);

const fresh = rows.filter((r) => {
  const t = new Date(r.created_at);
  return !isNaN(t) && t >= dayAgo;
});
const count = (c) => fresh.filter((r) => String(r.category).toUpperCase() === c).length;
const hot = fresh.filter((r) => String(r.category).toUpperCase() === 'HOT');
const due = rows.filter((r) => r.next_followup
  && String(r.next_followup).slice(0, 10) <= today
  && String(r.status).toUpperCase() !== 'CLOSED');

const line = (r) => `- ${r.name || 'Unknown'} (${r.company || 'no company'}) | score ${r.score} | ${r.recommended_action || ''}`;
const body = [
  `New leads in the last 24 hours: ${fresh.length}`,
  `HOT: ${count('HOT')} | WARM: ${count('WARM')} | COLD: ${count('COLD')}`,
  '',
  'HOT leads:',
  hot.length ? hot.map(line).join('\n') : '- None',
  '',
  'Follow-ups due:',
  due.length
    ? due.map((r) => `- ${r.name || 'Unknown'} (${r.company || ''}) | due ${String(r.next_followup).slice(0, 10)}`).join('\n')
    : '- None',
].join('\n');

return [{ json: { subject: `Daily lead summary: ${fresh.length} new, ${count('HOT')} HOT`, body } }];
